exercises.solution:
const pracownicy = [
  { imie: "Marta", wiek: 34 },
  { imie: "Tomek", wiek: 19 },
  { imie: "Ola", wiek: 41 }
];

const posortowani = [...pracownicy].sort((a, b) => a.wiek - b.wiek);
console.log(posortowani.map(p => `${p.imie}: ${p.wiek}`));
// ['Tomek: 19', 'Marta: 34', 'Ola: 41']

const pracownicy = [{ imie: "Zosia" }, { imie: "Ala" }, { imie: "Marek" }];
const posortowani = [...pracownicy].sort((a, b) => a.imie.localeCompare(b.imie));
console.log(posortowani.map(p => p.imie)); // ['Ala', 'Marek', 'Zosia']

const ceny1 = [100, 25, 9, 250, 3];
console.log([...ceny1].sort()); // [100, 25, 250, 3, 9] - BLEDNIE

const ceny2 = [100, 25, 9, 250, 3];
console.log([...ceny2].sort((a, b) => a - b)); // [3, 9, 25, 100, 250] - POPRAWNIE

const produkty = [
  { nazwa: "Kubek", cena: 25 },
  { nazwa: "Laptop", cena: 3000 },
  { nazwa: "Notes", cena: 15 }
];

const posortowane = [...produkty].sort((a, b) => b.cena - a.cena);
console.log(posortowane.map(p => p.nazwa)); // ['Laptop', 'Kubek', 'Notes']

function posortujRosnaco(tablica) {
  return [...tablica].sort((a, b) => a - b);
}

const oryginal = [7, 2, 9, 1];
console.log(posortujRosnaco(oryginal)); // [1, 2, 7, 9]
console.log(oryginal); // [7, 2, 9, 1] - NIEZMIENIONY

const produkty = [{ nazwa: "Laptop" }, { nazwa: "TV" }, { nazwa: "Sluchawki" }];
const posortowane = [...produkty].sort((a, b) => a.nazwa.length - b.nazwa.length);
console.log(posortowane.map(p => p.nazwa)); // ['TV', 'Laptop', 'Sluchawki']

const wydarzenia = [
  { data: "2024-06-15" },
  { data: "2024-01-10" },
  { data: "2024-12-25" }
];

const posortowane = [...wydarzenia].sort((a, b) => a.data < b.data ? -1 : 1);
console.log(posortowane.map(w => w.data));
// ['2024-01-10', '2024-06-15', '2024-12-25']

const uzytkownicy = [
  { imie: "Jan", punkty: 850 },
  { imie: "Ala", punkty: 1200 },
  { imie: "Kuba", punkty: 630 }
];

const ranking = [...uzytkownicy].sort((a, b) => b.punkty - a.punkty);
console.log(ranking[0]); // { imie: 'Ala', punkty: 1200 }

const teksty = ["10", "9", "2", "1"];

console.log([...teksty].sort()); // ['1', '10', '2', '9'] - BLEDNIE (leksykograficznie)
console.log([...teksty].sort((a, b) => Number(a) - Number(b))); // ['1', '2', '9', '10'] - POPRAWNIE

const produkty = [
  { nazwa: "A", dostepny: false },
  { nazwa: "B", dostepny: true },
  { nazwa: "C", dostepny: true }
];

const posortowane = [...produkty].sort((a, b) => (b.dostepny - a.dostepny));
console.log(posortowane.map(p => p.nazwa)); // ['B', 'C', 'A'] (kolejnosc B/C zachowana - sort stabilny)

function posortujMalejaco(tablica) {
  return [...tablica].sort((a, b) => b - a);
}

console.log(posortujMalejaco([4, 8, 1, 9, 3])); // [9, 8, 4, 3, 1]

const imiona = ["zosia", "Ala", "Barbara", "kuba"];
const posortowane = [...imiona].sort((a, b) =>
  a.localeCompare(b, undefined, { sensitivity: "base" })
);
console.log(posortowane); // ['Ala', 'Barbara', 'kuba', 'zosia']

