const posortowane = [...produkty].sort((a, b) => a.cena - b.cena);
console.log(posortowane.map(p => p.id)); // [3, 1, 2] - id 1 wciaz PRZED id 2 (oryginalna kolejnosc zachowana)

const zadania = [
  { nazwa: "Sprzatanie", priorytet: 3 },
  { nazwa: "Raport", priorytet: 1 },
  { nazwa: "Zakupy", priorytet: 2 }
];

const posortowane = [...zadania].sort((a, b) => a.priorytet - b.priorytet);
console.log(posortowane.map(z => z.nazwa)); // ['Raport', 'Zakupy', 'Sprzatanie']

