const posortowaneIOdwrocone = [...liczby].sort((a, b) => a - b).reverse();
const malejaco = [...liczby].sort((a, b) => b - a);

console.log(posortowaneIOdwrocone); // [9, 6, 5, 4, 3, 2, 1, 1]
console.log(malejaco);              // [9, 6, 5, 4, 3, 2, 1, 1]

const produkty = [
  { nazwa: "A", kategoria: "elektronika", cena: 200 },
  { nazwa: "B", kategoria: "biuro", cena: 50 },
  { nazwa: "C", kategoria: "elektronika", cena: 100 }
];

const posortowane = [...produkty].sort((a, b) =>
  a.kategoria.localeCompare(b.kategoria) || (a.cena - b.cena)
);
console.log(posortowane.map(p => p.nazwa)); // ['B', 'C', 'A']

const liczby = [100, 25, 9, 250, 3];
const posortowaneDomyslnie = [...liczby].sort();
const jakoStringi = [...liczby].map(String).sort();

console.log(posortowaneDomyslnie); // [100, 25, 250, 3, 9] - wciaz liczby
console.log(jakoStringi);          // ['100', '25', '250', '3', '9'] - teraz stringi
console.log(posortowaneDomyslnie.join(",") === jakoStringi.join(",")); // true - ta sama kolejnosc

const filmy = [
  { tytul: "Film A", ocena: 7.5 },
  { tytul: "Film B", ocena: 9.2 },
  { tytul: "Film C", ocena: 6.1 }
];

const posortowane = [...filmy].sort((a, b) => b.ocena - a.ocena);
console.log(posortowane[0].tytul); // "Film B"

const liczby = [5, 2, 8, 1, 9];
const wynik = liczby.sort((a, b) => a - b);

console.log(wynik);  // [1, 2, 5, 8, 9]
console.log(liczby); // [1, 2, 5, 8, 9] - oryginal ROWNIEZ zmutowany

const wyniki = [
  { imie: "Jan", wynik: 78 },
  { imie: "Ala", wynik: 92 },
  { imie: "Kuba", wynik: 65 }
];

const ranking = [...wyniki].sort((a, b) => b.wynik - a.wynik);
console.log(ranking[1].imie); // "Jan"

